const LBM=[];const lbLoad=()=>{try{return JSON.parse(localStorage.getItem('bp_lb')||'[]')}catch(e){return LBM.slice()}},lbSave=a=>{LBM.length=0;LBM.push(...a);try{localStorage.setItem('bp_lb',JSON.stringify(a.slice(-300)))}catch(e){}};
const sod=x=>new Date(x.getFullYear(),x.getMonth(),x.getDate()).getTime();
function inRange(ts,k){const n=new Date(),d=new Date(ts);if(k==='d')return sod(d)===sod(n);if(k==='w')return ts>=sod(n)-((n.getDay()+1)%7)*864e5;return d.getFullYear()===n.getFullYear()&&d.getMonth()===n.getMonth()}
const fm=x=>'৳'+bn(Math.round(x).toLocaleString('en-IN'));
const RANKS=[[0,'নতুন ড্রাইভার · এখনো মোড়ে কেউ চেনে না'],[50000,'মহল্লার ত্রাস'],[200000,'মোড়ের মাস্তান'],[500000,'ট্রাফিক সার্জেন্টের প্রিয় মেহমান'],[1000000,'চ্যাডের খুশির জাতীয় নায়ক']];
